function f(id,label,kind='input',value='',placeholder=''){return '<div class="field"><label for="'+id+'">'+esc(label)+'</label>'+(kind==='textarea'?'<textarea id="'+id+'" placeholder="'+esc(placeholder)+'">'+esc(value)+'</textarea>':'<input id="'+id+'" '+(kind==='password'?'type="password" autocomplete="current-password"':'type="text"')+' value="'+esc(value)+'" placeholder="'+esc(placeholder)+'">')+'</div>'}
